1	-- 博物馆借展与展柜微环境监测服务建表脚本（H2 MySQL 兼容模式）。
2	-- 所有时间戳均为 UTC；日期为 UTC 日界；温度单位摄氏度，湿度单位 %RH。
3	
4	CREATE TABLE IF NOT EXISTS artifact (
5	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
6	    name VARCHAR(128) NOT NULL,
7	    artifact_level VARCHAR(16) NOT NULL,
8	    material VARCHAR(32) NOT NULL
9	);
10	COMMENT ON TABLE artifact IS '文物档案（合成数据）';
11	COMMENT ON COLUMN artifact.id IS '文物主键';
12	COMMENT ON COLUMN artifact.name IS '文物名称';
13	COMMENT ON COLUMN artifact.artifact_level IS '文物等级：LEVEL_ONE 一级 / LEVEL_TWO 二级';
14	COMMENT ON COLUMN artifact.material IS '材质，决定展柜微环境温湿度区间：PAPER 纸质 / BRONZE 青铜 / GENERAL 一般';
15	
16	CREATE TABLE IF NOT EXISTS showcase (
17	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
18	    gallery VARCHAR(64) NOT NULL,
19	    material VARCHAR(32) NOT NULL,
20	    temp_min DECIMAL(5,2) NOT NULL,
21	    temp_max DECIMAL(5,2) NOT NULL,
22	    humidity_min DECIMAL(5,2) NOT NULL,
23	    humidity_max DECIMAL(5,2) NOT NULL,
24	    frozen BOOLEAN NOT NULL DEFAULT FALSE
25	);
26	COMMENT ON TABLE showcase IS '展柜（合成数据），按材质设定温湿度区间';
27	COMMENT ON COLUMN showcase.id IS '展柜主键';
28	COMMENT ON COLUMN showcase.gallery IS '所属展馆/展厅名称';
29	COMMENT ON COLUMN showcase.material IS '适配材质：PAPER 纸质 / BRONZE 青铜 / GENERAL 一般';
30	COMMENT ON COLUMN showcase.temp_min IS '温度下限（摄氏度，含边界）';
31	COMMENT ON COLUMN showcase.temp_max IS '温度上限（摄氏度，含边界）';
32	COMMENT ON COLUMN showcase.humidity_min IS '湿度下限（%RH，含边界）';
33	COMMENT ON COLUMN showcase.humidity_max IS '湿度上限（%RH，含边界）';
34	COMMENT ON COLUMN showcase.frozen IS '是否冻结新入藏：TRUE 表示紧急工单未处置，禁止新借展入藏';
35	
36	CREATE TABLE IF NOT EXISTS loan_contract (
37	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
38	    request_id VARCHAR(64) NOT NULL,
39	    artifact_id BIGINT NOT NULL,
40	    showcase_id BIGINT NOT NULL,
41	    borrower VARCHAR(128) NOT NULL,
42	    start_date DATE NOT NULL,
43	    end_date DATE NOT NULL,
44	    original_end_date DATE NOT NULL,
45	    extended BOOLEAN NOT NULL DEFAULT FALSE,
46	    status VARCHAR(32) NOT NULL,
47	    suspend_reason VARCHAR(64) DEFAULT NULL,
48	    version INT NOT NULL DEFAULT 0,
49	    created_at TIMESTAMP NOT NULL,
50	    updated_at TIMESTAMP NOT NULL
51	);
52	COMMENT ON TABLE loan_contract IS '借展合同，状态流转：APPLIED 申请→ON_DISPLAY 在展→RETURNED 归还点交完成→CLOSED 结案；SUSPENDED 为环境异常挂起';
53	COMMENT ON COLUMN loan_contract.id IS '合同主键';
54	COMMENT ON COLUMN loan_contract.request_id IS '受理申请的幂等请求号';
55	COMMENT ON COLUMN loan_contract.artifact_id IS '借展文物主键';
56	COMMENT ON COLUMN loan_contract.showcase_id IS '入藏展柜主键';
57	COMMENT ON COLUMN loan_contract.borrower IS '借展方名称';
58	COMMENT ON COLUMN loan_contract.start_date IS '借展开始日（UTC 日界，含当日）';
59	COMMENT ON COLUMN loan_contract.end_date IS '当前借展截止日（UTC 日界，含当日），续展后更新';
60	COMMENT ON COLUMN loan_contract.original_end_date IS '原始借展截止日，用于核算续展上限';
61	COMMENT ON COLUMN loan_contract.extended IS '是否已续展：TRUE 表示唯一一次续展已使用';
62	COMMENT ON COLUMN loan_contract.status IS '合同状态：APPLIED/ON_DISPLAY/SUSPENDED/RETURNED/CLOSED';
63	COMMENT ON COLUMN loan_contract.suspend_reason IS '挂起原因，NULL 表示未挂起';
64	COMMENT ON COLUMN loan_contract.version IS '乐观锁版本号';
65	COMMENT ON COLUMN loan_contract.created_at IS '创建时间（UTC）';
66	COMMENT ON COLUMN loan_contract.updated_at IS '最近更新时间（UTC）';
67	
68	CREATE TABLE IF NOT EXISTS artifact_active_loan (
69	    artifact_id BIGINT PRIMARY KEY,
70	    contract_id BIGINT NOT NULL
71	);
72	COMMENT ON TABLE artifact_active_loan IS '文物有效借展唯一约束表：同一文物同一时刻仅允许一个未结案合同';
73	COMMENT ON COLUMN artifact_active_loan.artifact_id IS '文物主键（主键即唯一约束）';
74	COMMENT ON COLUMN artifact_active_loan.contract_id IS '当前有效合同主键';
75	
76	CREATE TABLE IF NOT EXISTS handover (
77	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
78	    contract_id BIGINT NOT NULL,
79	    handover_type VARCHAR(16) NOT NULL,
80	    museum_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
81	    borrower_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
82	    created_at TIMESTAMP NOT NULL,
83	    completed_at TIMESTAMP DEFAULT NULL,
84	    CONSTRAINT uk_handover UNIQUE (contract_id, handover_type)
85	);
86	COMMENT ON TABLE handover IS '点交单：交付与归还点交均须馆方与借展方双方确认后生效';
87	COMMENT ON COLUMN handover.id IS '点交单主键';
88	COMMENT ON COLUMN handover.contract_id IS '所属合同主键';
89	COMMENT ON COLUMN handover.handover_type IS '点交类型：DELIVERY 交付点交 / RETURN 归还点交';
90	COMMENT ON COLUMN handover.museum_confirmed IS '馆方是否已确认';
91	COMMENT ON COLUMN handover.borrower_confirmed IS '借展方是否已确认';
92	COMMENT ON COLUMN handover.created_at IS '点交单创建时间（UTC）';
93	COMMENT ON COLUMN handover.completed_at IS '双方确认完成时间（UTC），NULL 表示未生效';
94	
95	CREATE TABLE IF NOT EXISTS resume_review (
96	    contract_id BIGINT NOT NULL,
97	    party VARCHAR(16) NOT NULL,
98	    reviewed_at TIMESTAMP NOT NULL,
99	    PRIMARY KEY (contract_id, party)
100	);
101	COMMENT ON TABLE resume_review IS '挂起恢复复核记录：馆方与借展方双方复核齐备后合同恢复在展';
102	COMMENT ON COLUMN resume_review.contract_id IS '合同主键';
103	COMMENT ON COLUMN resume_review.party IS '复核方：MUSEUM 馆方 / BORROWER 借展方';
104	COMMENT ON COLUMN resume_review.reviewed_at IS '复核时间（UTC）';
105	
106	CREATE TABLE IF NOT EXISTS climate_reading (
107	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
108	    showcase_id BIGINT NOT NULL,
109	    sampled_at TIMESTAMP NOT NULL,
110	    temperature DECIMAL(5,2) NOT NULL,
111	    humidity DECIMAL(5,2) NOT NULL,
112	    out_of_range BOOLEAN NOT NULL,
113	    late BOOLEAN NOT NULL DEFAULT FALSE,
114	    created_at TIMESTAMP NOT NULL,
115	    CONSTRAINT uk_reading UNIQUE (showcase_id, sampled_at)
116	);
117	COMMENT ON TABLE climate_reading IS '展柜微环境读数，按展柜+采样时刻去重，乱序按采样时刻归位';
118	COMMENT ON COLUMN climate_reading.id IS '读数主键';
119	COMMENT ON COLUMN climate_reading.showcase_id IS '展柜主键';
120	COMMENT ON COLUMN climate_reading.sampled_at IS '采样时刻（UTC）';
121	COMMENT ON COLUMN climate_reading.temperature IS '温度（摄氏度）';
122	COMMENT ON COLUMN climate_reading.humidity IS '湿度（%RH）';
123	COMMENT ON COLUMN climate_reading.out_of_range IS '是否越限：按展柜温湿度区间（含边界）判定';
124	COMMENT ON COLUMN climate_reading.late IS '是否迟到读数：TRUE 表示合同结案后到达，仅记录不参与越限判定';
125	COMMENT ON COLUMN climate_reading.created_at IS '入库时间（UTC）';
126	
127	CREATE TABLE IF NOT EXISTS protection_order (
128	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
129	    showcase_id BIGINT NOT NULL,
130	    contract_id BIGINT DEFAULT NULL,
131	    status VARCHAR(16) NOT NULL,
132	    created_at TIMESTAMP NOT NULL,
133	    deadline_at TIMESTAMP NOT NULL,
134	    confirmed_at TIMESTAMP DEFAULT NULL,
135	    escalated_at TIMESTAMP DEFAULT NULL,
136	    watermark_at TIMESTAMP DEFAULT NULL
137	);
138	COMMENT ON TABLE protection_order IS '保护工单：连续 3 个采样点越限自动生成，24 小时内须处置确认，逾期升级紧急';
139	COMMENT ON COLUMN protection_order.id IS '工单主键';
140	COMMENT ON COLUMN protection_order.showcase_id IS '展柜主键';
141	COMMENT ON COLUMN protection_order.contract_id IS '触发时在展合同主键，NULL 表示无在展合同';
142	COMMENT ON COLUMN protection_order.status IS '工单状态：OPEN 待处置 / CONFIRMED 已确认 / ESCALATED 已升级紧急';
143	COMMENT ON COLUMN protection_order.created_at IS '工单生成时间（UTC）';
144	COMMENT ON COLUMN protection_order.deadline_at IS '处置时限（UTC）= 生成时间 + 24 小时，恰满即升级';
145	COMMENT ON COLUMN protection_order.confirmed_at IS '处置确认时间（UTC），NULL 表示未确认';
146	COMMENT ON COLUMN protection_order.escalated_at IS '升级紧急时间（UTC），NULL 表示未升级';
147	COMMENT ON COLUMN protection_order.watermark_at IS '处置确认时的越限序列复位水位（采样时刻），NULL 表示未确认';
148	
149	CREATE TABLE IF NOT EXISTS late_reading_event (
150	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
151	    showcase_id BIGINT NOT NULL,
152	    sampled_at TIMESTAMP NOT NULL,
153	    recorded_at TIMESTAMP NOT NULL
154	);
155	COMMENT ON TABLE late_reading_event IS '迟到读数事件：合同结案后到达的读数仅记录事件，不参与判定';
156	COMMENT ON COLUMN late_reading_event.id IS '事件主键';
157	COMMENT ON COLUMN late_reading_event.showcase_id IS '展柜主键';
158	COMMENT ON COLUMN late_reading_event.sampled_at IS '采样时刻（UTC）';
159	COMMENT ON COLUMN late_reading_event.recorded_at IS '事件记录时间（UTC）';
160	
161	CREATE TABLE IF NOT EXISTS idempotency_record (
162	    request_id VARCHAR(64) PRIMARY KEY,
163	    fingerprint VARCHAR(128) NOT NULL,
164	    op_type VARCHAR(64) NOT NULL,
