COMMENT ON COLUMN protection_order.escalated_at IS '升级紧急时间（UTC），NULL 表示未升级';
COMMENT ON COLUMN protection_order.watermark_at IS '处置确认时的越限序列复位水位（采样时刻），NULL 表示未确认';

CREATE TABLE IF NOT EXISTS late_reading_event (
