 */
@Service
public class ImageHandoverService {

    /** 点交类型：出借（交付）点交。 */
    public static final String HANDOVER_DELIVERY = "DELIVERY";
    /** 点交类型：归还点交。 */
    public static final String HANDOVER_RETURN = "RETURN";

    /** 差异工单状态：进行中（未闭环）。 */
    public static final String ORDER_OPEN = "OPEN";
