                        + " WHERE id = ? AND status = ?",
                ORDER_RESOLVED, Timestamp.from(now), resolvedBy, orderId, ORDER_OPEN);
        if (updated == 0) {
            DifferenceOrder current = getOrder(orderId);
            if (ORDER_RESOLVED.equals(current.status())) {
