    /**
     * 合同是否存在未闭环（进行中）差异工单。
     */
    public boolean hasOpenOrder(long contractId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM contract_open_diff_order WHERE contract_id = ?",
                Integer.class, contractId);
