            }
            if (feature.value() == null || feature.value().isBlank()) {
                throw ApiException.badRequest("影像特征值不能为空：" + feature.key());
            }
            if (!keys.add(feature.key())) {
                throw ApiException.badRequest("影像特征项名称重复：" + feature.key());
            }
